    }
    pub const fn caption() -> Self {
        Self::styled(TextStyle::Caption)
    }
    pub const fn caption2() -> Self {
        Self::styled(TextStyle::Caption2)
    }

    /// A custom font family + size (SwiftUI `.font(.custom(name:size:))`).
