        Self {
            style: None,
            family: Some(family),
            size: Some(size),
            weight: None,
            design: None,
        }
    }

    /// A system font with an exact size.
    pub const fn system(size: f32) -> Self {
        Self {
            style: None,
            family: None,
            size: Some(size),
            weight: None,
            design: None,
        }
    }

    /// A system font with an exact size + weight.
