    }

    /// Bind the text to a signal (re-emits `SET_TEXT` when it changes).
    pub fn text_signal(&mut self, signal: impl IntoSignalId) -> &mut Self {
        self.binding = Some(signal.into_signal_id());
        self
    }
}

impl Text {
    /// A text node with the given content.
