//! Diff-based reactive emitter.
//!
//! The engine holds the application's retained view tree and emits the
//! declarative structure as `TREE`/`PARAMETER` opcodes into the 16-byte ring
//! buffer (VStack, HStack, Text, spacing, padding, alignment). It does not
//! compute rects or layout; native renderers lay out their own elements.
//!
//! Emission is diff-based: on each `emit` the engine compares the current tree
//! against a snapshot of what it last emitted and writes only the opcodes for
//! nodes that actually changed. An unchanged tree emits zero opcodes.
//!
//! The emit pass performs zero dynamic heap allocations in the steady state.
//!
//! ## Signals
//!
//! Nodes may bind their text or a property to a [`crate::SignalId`]. The engine
//! resolves those bindings during emit (recording the dependency) and re-emits
//! only the affected nodes on [`Engine::set_signal`] — no full tree walk.

use alloc::borrow::ToOwned;

display.text:
//! Diff-based reactive emitter.
//!
//! The engine holds the application's retained view tree and emits the
//! declarative structure as `TREE`/`PARAMETER` opcodes into the 16-byte ring
//! buffer (VStack, HStack, Text, spacing, padding, alignment). It does not
//! compute rects or layout; native renderers lay out their own elements.
//!
//! Emission is diff-based: on each `emit` the engine compares the current tree
//! against a snapshot of what it last emitted and writes only the opcodes for
//! nodes that actually changed. An unchanged tree emits zero opcodes.
//!
//! The emit pass performs zero dynamic heap allocations in the steady state.
//!
//! ## Signals
//!
//! Nodes may bind their text or a property to a [`crate::SignalId`]. The engine
//! resolves those bindings during emit (recording the dependency) and re-emits
//! only the affected nodes on [`Engine::set_signal`] — no full tree walk.

use alloc::borrow::ToOwned;
use alloc::collections::BTreeMap;
use alloc::string::{String, ToString};
use alloc::vec;
use alloc::vec::Vec;

use pathland_core::{category, meta, value_type, value_type_for, window_field, WindowMeta};
use pathland_core::{Guest, Opcode};

use crate::node::{component_type_id, Component, Node};
use crate::signal::{Dep, Runtime, Signal, SignalId, SignalValue, SignalValueKind, WritableSignal};
use crate::window::WindowMetadata;

/// Encode a `LIST` property's arena entry: `[u32 count][f32 × count]`
/// (spec/OPCODE.md §Value types — a `FIT_QUERY` threshold table).
fn encode_list(values: &[f32]) -> Vec<u8> {
    let mut bytes = vec![0u8; 4 + 4 * values.len()];
    bytes[0..4].copy_from_slice(&(values.len() as u32).to_le_bytes());
    for (i, value) in values.iter().enumerate() {
        let o = 4 + 4 * i;
        bytes[o..o + 4].copy_from_slice(&value.to_bits().to_le_bytes());
    }
    bytes
}

/// Per-node state the engine remembers from the last emission.
#[derive(Debug, Clone, PartialEq)]
struct SnapshotNode {
    component_type: u16,
    parent: Option<u32>,
    index: usize,
    text: Option<String>,
    properties: BTreeMap<u16, u32>,
    /// Last-emitted `STRING` properties: property → (value, arena offset). The
    /// arena offset is reused across passes so an unchanged string never
    /// re-allocates into the bump arena.
    string_properties: BTreeMap<u16, (String, u32)>,
    /// Last-emitted `LIST` properties: property → (values, arena offset). The
    /// arena offset is reused across passes so an unchanged list never
    /// re-allocates into the bump arena.
    list_properties: BTreeMap<u16, (Vec<f32>, u32)>,
    /// Last-emitted `DESIGN_TOKEN` refs: property → (token path, arena offset).
    /// The arena offset is reused across passes so an unchanged ref never
    /// re-allocates into the bump arena.
    token_refs: BTreeMap<u16, (String, u32)>,
    /// Generation stamp set on each emit pass; used to detect deleted nodes.
    gen: u64,
}

/// Result of an emission pass.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct EmitResult {
    /// Number of opcodes written to the ring.
    pub opcodes: usize,
}

/// The diff-based reactive emitter.
///
/// `Engine` keeps the snapshot of what was last emitted and owns the signal
/// store. Calling `emit` with a (possibly mutated) retained tree writes only
/// the delta opcodes; `set_signal` writes deltas for only the bound nodes.
pub struct Engine {
    /// nodeId to last emitted state (a preallocated slab; node ids are dense).
    snapshot: Vec<Option<SnapshotNode>>,
    /// Monotonic generation stamp for the current pass.
    gen: u64,
    /// Reactive signal runtime (values + computed/effects + node dependencies).
    store: Runtime,
    /// Window/surface metadata signal bindings (`META::SET_WINDOW_METADATA`).
    window: WindowMetadata,
    /// The last window metadata written to the wire (dedupe / clear detection).
    window_emitted: WindowMeta,
}

impl Default for Engine {
    fn default() -> Self {
        Self::new()
    }
}

impl Engine {
    pub fn new() -> Self {
        Self {
            snapshot: Vec::new(),
            gen: 0,
            store: Runtime::new(),
            window: WindowMetadata::new(),
            window_emitted: WindowMeta::new(),
        }
    }

    /// The shared reactive runtime (for creating typed signals / computeds).
    pub fn runtime(&self) -> Runtime {
        self.store.clone()
    }

    /// Reconcile `root` against the snapshot, emitting only changed opcodes.
    pub fn emit(
        &mut self,
        root: &Node,
        guest: &mut Guest<'_>,
    ) -> Result<EmitResult, pathland_core::RingError> {
        self.gen = self.gen.wrapping_add(1);
        // Rebuild the signal->node dependency index from scratch; reconcile
        // re-adds the bindings this tree actually uses, so stale subscriptions
        // vanish.
        self.store.clear_node_deps();
        // Window metadata is renderer-global, not part of the tree: emit the
        // initial values (and any rebind/clear) before the node opcodes.
        let mut out = self.emit_window_metadata(guest)?;
        self.reconcile_node(root, None, 0, guest, &mut out)?;

        for (id, slot) in self.snapshot.iter_mut().enumerate() {
            if let Some(s) = slot {
                if s.gen != self.gen {
                    if let Some(parent) = s.parent {
                        guest.remove_child(parent, id as u32)?;
                        out += 1;
                    }
                    guest.delete_node(id as u32)?;
                    out += 1;
                    *slot = None;
                }
            }
        }
        Ok(EmitResult { opcodes: out })
    }

    /// Number of nodes tracked in the snapshot (diagnostics).
    pub fn tracked_nodes(&self) -> usize {
        self.snapshot.iter().filter(|s| s.is_some()).count()
    }

    /// Bind the window/surface presentation metadata
    /// (`META::SET_WINDOW_METADATA`): title, description, locale. Values are
    /// signal-backed, so a route can drive them from a computed. The next
    /// [`Engine::emit`] writes the initial values; a subsequent
    /// [`Engine::set_signal`] writes only the changed field.
    pub fn bind_window_metadata(&mut self, metadata: WindowMetadata) {
        self.window = metadata;
    }

    /// Bind one window-metadata field to a signal (the flat/C-ABI form of
    /// [`Engine::bind_window_metadata`]).
    pub fn bind_window_field(&mut self, field: u16, signal: SignalId) {
        self.window.set_signal(field, signal);
    }

    /// Emit changed window-metadata fields. Unchanged fields write nothing; a
    /// field that became unset writes an empty string (clear).
    fn emit_window_metadata(
        &mut self,
        guest: &mut Guest<'_>,
    ) -> Result<usize, pathland_core::RingError> {
        let mut out = 0usize;
        for field in window_field::ALL {
            let value = self.window.signal(field).and_then(|id| {
                let value = self.store.get(id);
                value.to_text().map(ToOwned::to_owned)
            });
            let previous = self.window_emitted.get(field).map(ToOwned::to_owned);
            if value == previous {
                continue;
            }
            let text = value.as_deref().unwrap_or("");
            let offset = guest.alloc_str(text).map_err(|_| pathland_core::RingError::Full)?;
            guest.push_opcode(Opcode::new(
                category::META,
                meta::SET_WINDOW_METADATA,
                0,
                field as u32,
                offset,
                0,
            ))?;
            self.window_emitted.set(field, text);
            out += 1;
        }
        Ok(out)
    }

    /// Emit a global design-token override (`PARAMETER::SET_DESIGN_TOKEN`).
    /// Overrides are renderer-global and apply everywhere the renderer resolves
    /// tokens; a `dark.`-prefixed path overrides the dark variant
    /// (spec/TOKENS.md). Returns the arena offset of the token path.
    pub fn set_design_token(
        &mut self,
        path: &str,
        value_type: u8,
        value: u32,
        guest: &mut Guest<'_>,
    ) -> Result<u32, pathland_core::RingError> {
        guest.set_design_token(path, value_type, value)
    }

    /// Emit a batch of global design-token overrides ([`Theme`](crate::Theme))
    /// as `PARAMETER::SET_DESIGN_TOKEN` opcodes. `STRING`-valued overrides allocate
    /// their value into the guest arena first (the wire carries an arena ref).
    ///
    /// Overrides are renderer-global: they never re-emit nodes and are not part
    /// of the diff. Emit once at mount, before the tree.
    pub fn apply_theme(
        &mut self,
        theme: &crate::Theme,
        guest: &mut Guest<'_>,
    ) -> Result<(), pathland_core::RingError> {
        for (path, value) in theme.iter() {
            self.emit_token_override(path, value, guest)?;
        }
        Ok(())
    }

    /// Emit an adaptive theme ([`AdaptiveTheme`](crate::AdaptiveTheme)): the
    /// **light** theme's overrides as base tokens, the **dark** theme's with the
    /// `dark.` scheme prefix (spec/TOKENS.md).
    pub fn apply_adaptive_theme(
        &mut self,
        adaptive: &crate::AdaptiveTheme,
        guest: &mut Guest<'_>,
    ) -> Result<(), pathland_core::RingError> {
        self.apply_theme(&adaptive.light, guest)?;
        for (path, value) in adaptive.dark.iter() {
            let dark_path = if path.starts_with("dark.") {
                path.to_string()
            } else {
                alloc::format!("dark.{path}")
            };
            self.emit_token_override(&dark_path, value, guest)?;
        }
        Ok(())
    }

    /// Emit `META::RESET_THEME` (clear every application token override; the
    /// renderer falls back to its defaults). A replacement theme emits this
    /// immediately before its overrides in the same frame.
    pub fn reset_theme(
        &mut self,
        guest: &mut Guest<'_>,
    ) -> Result<(), pathland_core::RingError> {
        guest.push_opcode(Opcode::new(category::META, meta::RESET_THEME, 0, 0, 0, 0))
    }

    /// Emit `META::SET_COLOR_SCHEME`: force light/dark or restore platform
    /// detection (spec/TOKENS.md). The renderer re-resolves token references;
    /// no node is re-emitted.
    pub fn set_color_scheme(
        &mut self,
        mode: crate::ColorSchemeMode,
        guest: &mut Guest<'_>,
    ) -> Result<(), pathland_core::RingError> {
        guest.push_opcode(Opcode::new(
            category::META,
            meta::SET_COLOR_SCHEME,
            0,
            mode.code(),
            0,
            0,
        ))
    }

    /// Replace the theme at runtime: `RESET_THEME` then the new overrides in
    /// one frame (spec/DSL.md §7.3).
    pub fn replace_theme(
        &mut self,
        theme: &crate::Theme,
        guest: &mut Guest<'_>,
    ) -> Result<(), pathland_core::RingError> {
        self.reset_theme(guest)?;
        self.apply_theme(theme, guest)
    }

    /// Replace an adaptive theme at runtime (reset + light + `dark.` overrides).
    pub fn replace_adaptive_theme(
        &mut self,
        adaptive: &crate::AdaptiveTheme,
        guest: &mut Guest<'_>,
    ) -> Result<(), pathland_core::RingError> {
        self.reset_theme(guest)?;
        self.apply_adaptive_theme(adaptive, guest)
    }

    /// Emit one `SET_DESIGN_TOKEN` override, arena-allocating STRING values.
    fn emit_token_override(
        &mut self,
        path: &str,
        value: &pathland_core::tokens::TokenValue,
        guest: &mut Guest<'_>,
    ) -> Result<(), pathland_core::RingError> {
        use pathland_core::tokens::TokenValue;
        match value {
            TokenValue::Str(s) => {
                let ref_ = guest
                    .alloc_str(s)
                    .map_err(|_| pathland_core::RingError::Full)?;
                guest.set_design_token(path, value.value_type(), ref_)?;
            }
            _ => {
                if let Some(bits) = value.to_bits() {
                    guest.set_design_token(path, value.value_type(), bits)?;
                }
            }
        }
        Ok(())
    }

    // --- Signals ---

    /// Create a new (untyped) signal with an initial value.
    pub fn create_signal(&mut self, value: SignalValue) -> SignalId {
        self.store.create(value)
    }

    /// Create a typed writable signal with an initial value.
    pub fn signal<T: SignalValueKind>(&self, initial: T) -> WritableSignal<T> {
        self.store.signal(initial)
    }

    /// Create a typed **computed** signal (lazily evaluated, memoized).
    pub fn computed<T: SignalValueKind>(&self, compute: impl Fn() -> T + 'static) -> Signal<T> {
        self.store.computed(compute)
    }

    /// Register an **effect** (runs immediately, then on dependency change).
    pub fn effect(&self, run: impl Fn() + 'static) {
        self.store.effect(run);
    }

    /// Read a typed signal's current value.
    pub fn read<T: SignalValueKind>(&self, signal: Signal<T>) -> Option<T> {
        signal.get()
    }

    /// Write a typed writable signal and re-emit only the nodes bound to it.
    pub fn set<T: SignalValueKind>(
        &mut self,
        signal: WritableSignal<T>,
        value: T,
        guest: &mut Guest<'_>,
    ) -> Result<usize, pathland_core::RingError> {
        self.set_signal(signal.id(), value.into_signal_value(), guest)
    }

    /// Read a signal's current value.
    pub fn get_signal(&self, id: SignalId) -> Option<SignalValue> {
        Some(self.store.get(id))
    }

    /// Replace a signal's value and re-emit only the nodes that depend on it
    /// (including nodes bound to any computed signal it feeds).
    ///
    /// Writes `SET_PROPERTY` / `SET_TEXT` deltas for the bound nodes whose
    /// materialized value changed. Returns the number of opcodes written.
    pub fn set_signal(
        &mut self,
        id: SignalId,
        value: SignalValue,
        guest: &mut Guest<'_>,
    ) -> Result<usize, pathland_core::RingError> {
        let changed = self.store.set(id, value);
        let mut out = 0usize;
        for cell in changed {
            out += self.emit_cell(cell, guest)?;
        }
        // A window-metadata signal (or a computed feeding one) changed. Fields
        // are compared, so an unrelated signal emits zero opcodes.
        out += self.emit_window_metadata(guest)?;
        Ok(out)
    }

    /// Re-emit the node bindings on one (changed) signal.
    fn emit_cell(
        &mut self,
        id: SignalId,
        guest: &mut Guest<'_>,
    ) -> Result<usize, pathland_core::RingError> {
        let deps: Vec<Dep> = self.store.node_deps(id);
        if deps.is_empty() {
            return Ok(0);
        }
        let value = self.store.get(id);
        let mut out = 0usize;
        for dep in deps {
            match dep {
                Dep::Text { node } => {
                    let new_text: Option<String> = value.to_text().map(ToOwned::to_owned);
                    let prev_text = self.snapshot_text(node);
                    if new_text.as_deref() != prev_text {
                        if let Some(t) = new_text.as_deref() {
                            guest.set_text(node, t)?;
                            out += 1;
                        }
                        if let Some(s) = self.snapshot_mut(node) {
                            s.text = new_text;
                        }
                    }
                }
                Dep::Property { node, prop } => {
                    let new_value = value.to_property_u32();
                    let prev_value = self.snapshot_property(node, prop);
                    if new_value != prev_value {
                        if let Some(v) = new_value {
                            guest.set_property(node, prop, value_type_for(prop), v)?;
                            out += 1;
                        }
                        if let Some(s) = self.snapshot_mut(node) {
                            match new_value {
                                Some(v) => {
                                    s.properties.insert(prop, v);
                                }
                                None => {
                                    s.properties.remove(&prop);
                                }
                            }
                        }
                    }
                }
                Dep::StringProperty { node, prop } => {
                    let new_text: Option<String> = value.to_text().map(ToOwned::to_owned);
                    let prev_text = self.snapshot_string(node, prop).map(ToOwned::to_owned);
                    if new_text != prev_text {
                        let emitted = match new_text.as_deref() {
                            Some(t) => {
                                let arena = guest
                                    .alloc_str(t)
                                    .map_err(|_| pathland_core::RingError::Full)?;
                                guest.set_property(node, prop, value_type::STRING, arena)?;
                                out += 1;
                                Some((t.to_string(), arena))
                            }
                            None => None,
                        };
                        if let Some(s) = self.snapshot_mut(node) {
                            match emitted {
                                Some((v, arena)) => {
                                    s.string_properties.insert(prop, (v, arena));
                                }
                                None => {
                                    s.string_properties.remove(&prop);
                                }
                            }
                        }
                    }
                }
            }
        }
        Ok(out)
    }

    fn snapshot_mut(&mut self, node: u32) -> Option<&mut SnapshotNode> {
        self.snapshot
            .get_mut(node as usize)
            .and_then(|s| s.as_mut())
    }

    fn snapshot_text(&self, node: u32) -> Option<&str> {
        self.snapshot
            .get(node as usize)
            .and_then(|s| s.as_ref())
            .and_then(|s| s.text.as_deref())
    }

    fn snapshot_property(&self, node: u32, prop: u16) -> Option<u32> {
        self.snapshot
            .get(node as usize)
            .and_then(|s| s.as_ref())
            .and_then(|s| s.properties.get(&prop).copied())
    }

    fn snapshot_string(&self, node: u32, prop: u16) -> Option<&str> {
        self.snapshot
            .get(node as usize)
            .and_then(|s| s.as_ref())
            .and_then(|s| s.string_properties.get(&prop))
            .map(|(value, _)| value.as_str())
    }

    fn slot_mut(&mut self, id: u32) -> &mut Option<SnapshotNode> {
        let idx = id as usize;
        if self.snapshot.len() <= idx {
            self.snapshot.resize(idx + 1, None);
        }
        &mut self.snapshot[idx]
    }

    #[allow(clippy::too_many_arguments)]
    fn reconcile_node(
        &mut self,
        node: &Node,
        parent: Option<u32>,
        index: usize,
        guest: &mut Guest<'_>,
        out: &mut usize,
    ) -> Result<(), pathland_core::RingError> {
        let component_type = component_type_id(&node.component);

        // Resolve bindings (owned) before taking the mutable snapshot borrow.
        let bound_text: Option<String> = node
            .text_binding
            .map(|sid| self.store.get(sid))
            .and_then(|v| v.to_text().map(ToOwned::to_owned));

        let merged_props: Option<BTreeMap<u16, u32>> = if node.property_bindings.is_empty() {
            None
        } else {
            let mut m = node.properties.clone();
            for (prop, sid) in &node.property_bindings {
                if let Some(v) = self.store.get(*sid).to_property_u32() {
                    m.insert(*prop, v);
                }
            }
            Some(m)
        };

        // `STRING`-valued property bindings (e.g. a media controller's
        // `MEDIA_SOURCE`) resolve on top of the static string properties.
        let merged_strings: Option<BTreeMap<u16, String>> = if node.string_bindings.is_empty() {
            None
        } else {
            let mut m = node.string_properties.clone();
            for (prop, sid) in &node.string_bindings {
                if let Some(v) = self.store.get(*sid).to_text() {
                    m.insert(*prop, v.to_string());
                }
            }
            Some(m)
        };

        let text_borrowed: Option<&str> = match (&bound_text, &node.component) {
            (Some(s), _) => Some(s.as_str()),
            (None, Component::Text { text }) => Some(text.as_str()),
            (None, Component::Button { label }) => Some(label.as_str()),
            _ => None,
        };
        let props: &BTreeMap<u16, u32> = merged_props.as_ref().unwrap_or(&node.properties);
        let token_refs = &node.token_properties;
        let strings: &BTreeMap<u16, String> = merged_strings
            .as_ref()
            .unwrap_or(&node.string_properties);
        let lists = &node.list_properties;

        let prev = self.slot_mut(node.id).take();
        let token_changed = match &prev {
            Some(p) => p.token_refs.len() != token_refs.len()
                || p.token_refs
                    .iter()
                    .any(|(prop, (old, _))| token_refs.get(prop) != Some(old)),
            None => !token_refs.is_empty(),
        };
        let strings_changed = match &prev {
            Some(p) => {
                p.string_properties.len() != strings.len()
                    || p.string_properties
                        .iter()
                        .any(|(prop, (old, _))| strings.get(prop) != Some(old))
            }
            None => !strings.is_empty(),
        };
        let lists_changed = match &prev {
            Some(p) => {
                p.list_properties.len() != lists.len()
                    || p.list_properties
                        .iter()
                        .any(|(prop, (old, _))| lists.get(prop) != Some(old))
            }
            None => !lists.is_empty(),
        };
        let props_changed = match &prev {
            Some(p) => &p.properties != props || token_changed || strings_changed || lists_changed,
            None => !props.is_empty() || !token_refs.is_empty() || !strings.is_empty() || !lists.is_empty(),
        };
        let text_changed = match &prev {
            Some(p) => p.text.as_deref() != text_borrowed,
            None => text_borrowed.is_some(),
        };

        // Token-ref emission. Built only on mount or when a ref changed, so a
        // steady-state pass performs no heap allocations (the unchanged refs'
        // arena offsets are reused from the previous snapshot below).
        let mut token_emit: Option<BTreeMap<u16, (String, u32)>> = None;
        // String-property emission, built only on mount / when a value changed
        // (arena offsets reused from the previous snapshot otherwise).
        let mut string_emit: Option<BTreeMap<u16, (String, u32)>> = None;
        // List-property emission, built only on mount / when a value changed
        // (arena offsets reused from the previous snapshot otherwise).
        let mut list_emit: Option<BTreeMap<u16, (Vec<f32>, u32)>> = None;

        // Properties in two passes — literals (skipping token-ref'd ids) then
        // token refs — so the steady-state emit performs no heap allocations.
        match &prev {
            None => {
                guest.create_node(node.id, component_type)?;
                *out += 1;
                if let Some(p) = parent {
                    guest.insert_child(p, node.id, index as u32)?;
                    *out += 1;
                }
                for (prop, value) in props {
                    if token_refs.contains_key(prop) {
                        continue;
                    }
                    guest.set_property(node.id, *prop, value_type_for(*prop), *value)?;
                    *out += 1;
                }
                if !token_refs.is_empty() {
                    let mut m = BTreeMap::new();
                    for (prop, path) in token_refs {
                        let arena = guest
                            .alloc_str(path)
                            .map_err(|_| pathland_core::RingError::Full)?;
                        guest.set_property(node.id, *prop, value_type::DESIGN_TOKEN, arena)?;
                        *out += 1;
                        m.insert(*prop, (path.clone(), arena));
                    }
                    token_emit = Some(m);
                }
                if !strings.is_empty() {
                    let mut m = BTreeMap::new();
                    for (prop, value) in strings {
                        let arena = guest
                            .alloc_str(value)
                            .map_err(|_| pathland_core::RingError::Full)?;
                        guest.set_property(node.id, *prop, value_type::STRING, arena)?;
                        *out += 1;
                        m.insert(*prop, (value.clone(), arena));
                    }
                    string_emit = Some(m);
                }
                if !lists.is_empty() {
                    let mut m = BTreeMap::new();
                    for (prop, values) in lists {
                        let bytes = encode_list(values);
                        let arena = guest
                            .alloc(&bytes)
                            .map_err(|_| pathland_core::RingError::Full)?;
                        guest.set_property(node.id, *prop, value_type::LIST, arena)?;
                        *out += 1;
                        m.insert(*prop, (values.clone(), arena));
                    }
                    list_emit = Some(m);
                }
                if let Some(t) = text_borrowed {
                    guest.set_text(node.id, t)?;
                    *out += 1;
                }
            }
            Some(p) => {
                if p.parent != parent {
                    if let Some(old) = p.parent {
                        guest.remove_child(old, node.id)?;
                        *out += 1;
                    }
                    if let Some(new) = parent {
                        guest.insert_child(new, node.id, index as u32)?;
                        *out += 1;
                    }
                } else if p.index != index {
                    if let Some(par) = parent {
                        guest.move_child(par, node.id, index as u32)?;
                        *out += 1;
                    }
                }
                if p.component_type != component_type {
                    guest.create_node(node.id, component_type)?;
                    *out += 1;
                }
                if text_changed {
                    if let Some(t) = text_borrowed {
                        guest.set_text(node.id, t)?;
                        *out += 1;
                    }
                }
                for (prop, value) in props {
                    if token_refs.contains_key(prop) {
                        continue;
                    }
                    if p.properties.get(prop) != Some(value) {
                        guest.set_property(node.id, *prop, value_type_for(*prop), *value)?;
                        *out += 1;
                    }
                }
                if token_changed {
                    let mut m = BTreeMap::new();
                    for (prop, path) in token_refs {
                        let (arena, changed) = match p.token_refs.get(prop) {
                            Some((old_path, old_offset)) if old_path == path => (*old_offset, false),
                            _ => {
                                let offset = guest
                                    .alloc_str(path)
                                    .map_err(|_| pathland_core::RingError::Full)?;
                                (offset, true)
                            }
                        };
                        m.insert(*prop, (path.clone(), arena));
                        if changed {
                            guest.set_property(node.id, *prop, value_type::DESIGN_TOKEN, arena)?;
                            *out += 1;
                        }
                    }
                    token_emit = Some(m);
                }
                if strings_changed {
                    let mut m = BTreeMap::new();
                    for (prop, value) in strings {
                        let (arena, changed) = match p.string_properties.get(prop) {
                            Some((old_value, old_offset)) if old_value == value => {
                                (*old_offset, false)
                            }
                            _ => {
                                let offset = guest
                                    .alloc_str(value)
                                    .map_err(|_| pathland_core::RingError::Full)?;
                                (offset, true)
                            }
                        };
                        m.insert(*prop, (value.clone(), arena));
                        if changed {
                            guest.set_property(node.id, *prop, value_type::STRING, arena)?;
                            *out += 1;
                        }
                    }
                    string_emit = Some(m);
                }
                if lists_changed {
                    let mut m = BTreeMap::new();
                    for (prop, values) in lists {
                        let (arena, changed) = match p.list_properties.get(prop) {
                            Some((old_values, old_offset)) if old_values == values => {
                                (*old_offset, false)
                            }
                            _ => {
                                let bytes = encode_list(values);
                                let offset = guest
                                    .alloc(&bytes)
                                    .map_err(|_| pathland_core::RingError::Full)?;
                                (offset, true)
                            }
                        };
                        m.insert(*prop, (values.clone(), arena));
                        if changed {
                            guest.set_property(node.id, *prop, value_type::LIST, arena)?;
                            *out += 1;
                        }
                    }
                    list_emit = Some(m);
                }
            }
        }

        let mut prev_props = None;
        let mut prev_text = None;
        let mut prev_token_refs = None;
        let mut prev_strings = None;
        let mut prev_lists = None;
        if let Some(p) = prev {
            if !props_changed {
                prev_props = Some(p.properties);
            }
            if !text_changed {
                prev_text = p.text;
            }
            if !token_changed {
                prev_token_refs = Some(p.token_refs);
            }
            if !strings_changed {
                prev_strings = Some(p.string_properties);
            }
            if !lists_changed {
                prev_lists = Some(p.list_properties);
            }
            let _ = p;
        }
        let properties = match prev_props {
            Some(props) => props,
            None => props.clone(),
        };
        let text = match prev_text {
            Some(t) => Some(t),
            None => text_borrowed.map(|s| s.to_owned()),
        };
        let token_refs_snapshot = match token_emit {
            Some(m) => m,
            None => prev_token_refs.unwrap_or_default(),
        };
        let string_properties = match string_emit {
            Some(m) => m,
            None => prev_strings.unwrap_or_default(),
        };
        let list_properties = match list_emit {
            Some(m) => m,
            None => prev_lists.unwrap_or_default(),
        };
        *self.slot_mut(node.id) = Some(SnapshotNode {
            component_type,
            parent,
            index,
            text,
            properties,
            string_properties,
            list_properties,
            token_refs: token_refs_snapshot,
            gen: self.gen,
        });

        // Record signal dependencies for this node.
        if let Some(sid) = node.text_binding {
            self.store.add_node_dep(sid, Dep::Text { node: node.id });
        }
        for (prop, sid) in &node.property_bindings {
            self.store
                .add_node_dep(*sid, Dep::Property { node: node.id, prop: *prop });
        }
        for (prop, sid) in &node.string_bindings {
            self.store
                .add_node_dep(*sid, Dep::StringProperty { node: node.id, prop: *prop });
        }

        for (i, child) in node.children.iter().enumerate() {
            self.reconcile_node(child, Some(node.id), i, guest, out)?;
        }
        Ok(())
    }
}

