#[test]
fn grid_config_emits_counts() {
    let node = Grid::with(|g| {
        g.columns(2.0).rows(3.0).spacing(4.0);
    })
    .children(vec![Box::new(text("a"))])
    .build();
    assert_eq!(node.component, Component::Grid);
    assert_eq!(
